constexpr int MOD = 998244353;

int n, k;
vector<int> v;
int ans = 0;

int weight(int x) {
    if (k == 1) return x;
    return (x * x + x) / 2;
}

bool check(int sz) {
    vector<int> a(v.begin(), v.begin() + sz);

    long long sum = accumulate(a.begin(), a.end(), 0LL);
    if (sum > n) return false;

    for (int it = 0; it < k - 1; ++it) {
        sort(a.begin(), a.end(), greater<int>());

        long long nextSum = 0;
        for (int i = 0; i < (int)a.size(); ++i) {
            nextSum += 1LL * (i + 1) * a[i];
            if (nextSum > n) return false;
        }

        vector<int> b;
        b.reserve(static_cast<size_t>(sum));
        for (int i = 0; i < (int)a.size(); ++i) {
            b.insert(b.end(), a[i], i + 1);
        }

        a.swap(b);
        sum = nextSum;
    }

    return true;
}

void go(int pos) {
    v[pos] = 1;

    while (check(pos + 1)) {
        ++ans;
        go(pos + 1);
        ++v[pos];

